{"command":"python3 - <<'PY'
import os, pty, subprocess, time, select
master, slave = pty.openpty()
env=os.environ.copy(); env['TERM']='xterm'; env['COLUMNS']='80'; env['LINES']='24'
p=subprocess.Popen(['./executable'], stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
os.close(slave)
data=b''; sent=False; start=time.time()
while time.time()-start<2:
    r,_,_=select.select([master],[],[],0.05)
    if r:
        try: data += os.read(master,4096)
        except OSError: break
    if not sent and time.time()-start>0.3:
        os.write(master,b'q'); sent=True
    if p.poll() is not None: break
if p.poll() is None:
    p.terminate(); p.wait()
os.close(master)
print('rc',p.returncode,'bytes',len(data),'hasTasks',b'Tasks' in data,'hasQuit',b'F10Quit' in data)
PY"}
